const DICTS = { fa, en, ru };
let current = 'en';

export function setLanguage(lang) {
  current = DICTS[lang] ? lang : 'fa';
  document.documentElement.lang = current;
  document.documentElement.dir = current === 'fa' ? 'rtl' : 'ltr';
}

export function lang() { return current; }

/** Locale for dates and region names. */
export function locale() { return current === 'fa' ? 'fa-IR' : current === 'ru' ? 'ru-RU' : 'en-GB'; }

export function t(key, vars) {
  let s = DICTS[current][key] ?? DICTS.en[key] ?? key;
  if (vars) for (const [k, v] of Object.entries(vars)) s = s.split(`{${k}}`).join(String(v));
  return s;
}

const FA_DIGITS = '۰۱۲۳۴۵۶۷۸۹';
/** Format a number for display (Persian digits in Persian UI). Technical values (ports, IPs) stay Latin. */
export function num(n, opts) {
  const s = typeof n === 'number' ? n.toLocaleString(current === 'ru' ? 'ru-RU' : 'en-US', opts) : String(n);
  return current === 'fa' ? s.replace(/\d/g, (d) => FA_DIGITS[d]).replace(/(?<=[۰-۹])\.(?=[۰-۹])/g, '٫').replace(/(?<=[۰-۹]),(?=[۰-۹])/g, '٬') : s;
}
